---@param config LuckRotaryTableConfig
function LuckRotaryTableDataManager:SetCurConfig(config)
    self.curConfig=config
    self:InitActData()
end

---@return  LuckRotaryTableConfig
function LuckRotaryTableDataManager:GetCurConfig()
    return self.curConfig
end

function LuckRotaryTableDataManager:InitActData()
    for i, v in pairs(LuckRotaryTableConfigDefault) do
        self.LuckRotaryDataTab[v.actId]={}
        self:InitActLuckRotaryTable(self.LuckRotaryDataTab[v.actId])
    end
end

