function LuckRotaryTableDataManager:GetLuckRotaryDataByIndex(index)
    if self.LuckRotaryDataTab[self.curConfig.actId] and self.LuckRotaryDataTab[self.curConfig.actId][index] then
        return self.LuckRotaryDataTab[self.curConfig.actId][index]
    end
end

---@return number
function LuckRotaryTableDataManager:GetLotteryTicketNum()
    return self.curConfig:GetLotteryTicketNum()
end

function LuckRotaryTableDataManager:InitActLuckRotaryTable(actLuckRotaryTable)-----不同转盘需要自己定义奖品
   if  self.curConfig == LuckRotaryTableConfigDefault.SpringFestival then
       ---@type dictluckytablenew_config
       local tab = ClientDataManager:Get():GetDataTable(ConfigNames.dictluckytable_config)
       ---@type dictluckytablenew_config_cell[]
       local configTab = tab.GetDataListByTableId(self.curConfig.actId)
       for i = 1, #configTab do
           local data = LuckRotaryTableData(configTab[i].seq,configTab[i].propsid,configTab[i].propsnum,configTab[i].hitflag==1)
           actLuckRotaryTable[configTab[i].seq] = data
       end
   end
end

